    std::string Upper(
      std::string s
    )
    {
      std::transform(s.begin(), s.end(), s.begin(), [](const unsigned char c) {
        return static_cast<char>(std::toupper(c));
      });
      return s;
    }

    std::string Lower(
      std::string s
    )
    {
      std::transform(s.begin(), s.end(), s.begin(), [](const unsigned char c) {
        return static_cast<char>(std::tolower(c));
      });
      return s;
    }

    double Num(
      const JsonTree* n,
      const char* key,
      const double fallback
    )
    {
      return n != nullptr ? n->Num(key, fallback) : fallback;
    }

    std::string FactionCat(
      const std::string& f
    )
    {
      return f == "Aeon" ? "AEON" : f == "Cybran" ? "CYBRAN" : f == "Seraphim" ? "SERAPHIM" : "UEF";
    }

    char FactionLetter(
      const std::string& f
    )
    {
      return f == "Aeon" ? 'a' : f == "Cybran" ? 'r' : f == "Seraphim" ? 's' : 'e';
    }

    std::array<float, 3> DonorDims(
      const JsonTree& d
    )
    {
      const float us = d.Float("uniformScale", 0.1f);
      const JsonTree* b = d.Get("bounds");
      if (b == nullptr || b->items.size() < 6) {
        return {1.0f, 1.0f, 1.0f};
      }
      const auto at = [b](const int i) {
        return static_cast<float>(b->items[static_cast<std::size_t>(i)].n);
      };
      return {(at(3) - at(0)) * us, (at(4) - at(1)) * us, (at(5) - at(2)) * us};
    }

    float SkeletonScale(
      const JsonTree& d,
      const UnitWizardSpec& spec
    )
    {
      const std::array<float, 3> dims = DonorDims(d);
      const float len = std::max(dims[0], dims[2]);
      if (len < 0.001f) {
        return 1.0f;
      }
      return (spec.mesh.length > 0.0f ? spec.mesh.length : len) / len;
    }

    JsonTree Copy(
      const JsonTree* n
    )
    {
      return n != nullptr ? *n : JsonTree::MakeObject();
    }

    JsonTree& Field(
      JsonTree& t,
      const std::string& key
    )
    {
      if (const JsonTree* existing = t.Get(key); existing == nullptr) {
        return t.Set(key, JsonTree::MakeObject());
      }
      for (auto& [k, v] : t.fields) {
        if (k == key) {
          if (v.kind != JsonTree::Kind::Object && v.kind != JsonTree::Kind::Array) {
            v = JsonTree::MakeObject();
          }
          return v;
        }
      }
      return t.Set(key, JsonTree::MakeObject());
    }

    void Remove(
      JsonTree& t,
      const std::string& key
    )
    {
      t.fields.erase(
        std::remove_if(
          t.fields.begin(),
          t.fields.end(),
          [&key](const auto& f) {
        return f.first == key;
      }
        ),
        t.fields.end()
      );
    }

    JsonTree SoundOf(
      const JsonTree& v
    )
    {
      JsonTree s = v;
      s.kind = JsonTree::Kind::Object;
      s.Set("__call", JsonTree::Text("Sound"));
      return s;
    }

    float R2(
      const float v
    )
    {
      return std::floor(v * 100.0f + 0.5f) / 100.0f;
    }

    struct WeaponBones
    {
      std::string yaw;
      std::string pitch;
      std::string muzzle;
      JsonTree racks;
      bool turreted = false;
      bool any = false;
    };

    WeaponBones BonesOfWeapon(
      const UnitWizardData& data,
      const UnitWizardSpec& spec,
      const std::vector<std::string>& groups
    )
    {
      WeaponBones out;
      const JsonTree* d = data.Donor(data.DonorOf(spec.templateId, spec.faction));
      if (spec.mesh.skeleton == "template" || groups.empty()) {
        const JsonTree* w = d != nullptr ? d->Get("weapon") : nullptr;
        if (w == nullptr || w->Get("muzzle") == nullptr) {
          return out;
        }
        out.yaw = w->Str("yaw", "");
        out.pitch = w->Str("pitch", "");
        out.muzzle = w->Str("muzzle", "");
        out.racks = Copy(w->Get("racks"));
        out.turreted = w->Bool("turreted", false);
        out.any = true;
        return out;
      }
      for (const std::string& g : groups) {
        const std::string l = Lower(g);
        if (out.yaw.empty() && (l.contains("turret") || l.contains("yaw"))) {
          out.yaw = g;
        }
        if (out.pitch.empty() && (l.contains("barrel") || l.contains("pitch") || l.contains("gun"))) {
          out.pitch = g;
        }
        if (out.muzzle.empty() && l.contains("muzzle")) {
          out.muzzle = g;
        }
      }
      if (out.muzzle.empty()) {
        out.muzzle = !out.pitch.empty() ? out.pitch : out.yaw;
      }
      if (out.muzzle.empty()) {
        return out;
      }
      if (out.pitch.empty()) {
        out.pitch = out.yaw;
      }
      JsonTree rack = JsonTree::MakeObject();
      rack.Set("RackBone", JsonTree::Text(!out.pitch.empty() ? out.pitch : out.muzzle));
      JsonTree muzzles = JsonTree::MakeArray();
      muzzles.Push(JsonTree::Text(out.muzzle));
      rack.Set("MuzzleBones", std::move(muzzles));
      out.racks = JsonTree::MakeArray();
      out.racks.Push(std::move(rack));
      out.turreted = !out.yaw.empty();
      out.any = true;
      return out;
    }

    bool IsArray(
      const JsonTree& t
    )
    {
      return t.fields.empty() || (t.fields.size() == 1 && t.fields[0].first == "__call" && !t.items.empty());
    }

    std::string NumText(
      const double v
    )
    {
      char text[48];
      if (v == std::floor(v) && std::abs(v) < 1e9) {
        (void)std::snprintf(text, sizeof(text), "%.0f", v);
      } else {
        (void)std::snprintf(text, sizeof(text), "%.6g", v);
      }
      return text;
    }

    std::string Quote(
      const std::string& s
    )
    {
      std::string out = "\"";
      for (const char c : s) {
        switch (c) {
        case '"':
          out += "\\\"";
          break;
        case '\\':
          out += "\\\\";
          break;
        case '\n':
          out += "\\n";
          break;
        case '\r':
          break;
        default:
          out += c;
          break;
        }
      }
      return out + "\"";
    }

    std::string Key(
      const std::string& k
    )
    {
      bool plain = !k.empty() && (std::isalpha(static_cast<unsigned char>(k[0])) != 0 || k[0] == '_');
      for (const char c : k) {
        plain = plain && (std::isalnum(static_cast<unsigned char>(c)) != 0 || c == '_');
      }
      return plain ? k : "[" + Quote(k) + "]";
    }

    bool ReadText(
      const std::filesystem::path& path,
      std::string& out
    )
    {
      std::ifstream in(path, std::ios::binary);
      if (!in) {
        return false;
      }
      out.assign(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
      return true;
    }

    bool WriteBytes(
      const std::filesystem::path& path,
      const void* data,
      const std::size_t size
    )
    {
      std::error_code ec;
      std::filesystem::create_directories(path.parent_path(), ec);
      std::ofstream out(path, std::ios::binary | std::ios::trunc);
      out.write(static_cast<const char*>(data), static_cast<std::streamsize>(size));
      return static_cast<bool>(out);
    }
