  const JsonTree* UnitWizardData::Donor(
    const std::string& id
  ) const
  {
    const JsonTree* donors = root.Get("Donors");
    return donors != nullptr ? donors->Get(id) : nullptr;
  }

  std::string UnitWizardData::DonorOf(
    const std::string& templateId,
    const std::string& faction
  ) const
  {
    const JsonTree* map = root.Get("Map");
    const JsonTree* t = map != nullptr ? map->Get(templateId) : nullptr;
    return t != nullptr ? t->Str(faction, "") : std::string();
  }

  std::expected<void, std::string> LoadUnitWizardData(
    const std::string& text,
    UnitWizardData& out
  )
  {
    if (auto read = ParseLuaAssignments(text, out.root); !read) {
      return read;
    }
    if (out.root.Get("Donors") == nullptr || out.root.Get("Map") == nullptr) {
      return std::unexpected("the wizard data has no Donors or Map");
    }
    return {};
  }

