  const char* UnitWeaponKindName(
    const std::string& kind
  )
  {
    if (kind == "direct") {
      return "Direct fire gun";
    }
    if (kind == "cannon") {
      return "Cannon";
    }
    if (kind == "artillery") {
      return "Artillery";
    }
    if (kind == "aa") {
      return "Anti air";
    }
    if (kind == "missile") {
      return "Missile";
    }
    if (kind == "torpedo") {
      return "Torpedo";
    }
    if (kind == "bomb") {
      return "Bomb";
    }
    return "Weapon";
  }

